cd /scr/wurgaft/auto-psych/agent_trees/45bd45c333332e1a/repo/_runs/cell_1/experiment3/model_loop/iter_2/candidate_4
cat > scratch/ord.py << 'EOF'
exec(open('scratch/bys.py').read().split("for c in ['ex'")[0])
order=[];side=[];d=[]
for r in rows:
    s=[int(x) for x in r['number_set'].split(',')]; t=int(r['target'])
    order.append('last=max' if s[-1]==max(s) else ('last=min' if s[-1]==min(s) else 'mid'))
    side.append('below' if t<min(s) else ('above' if t>max(s) else 'in'))
    d.append(min(abs(t-min(s)),abs(t-max(s))))
order=np.array(order); side=np.array(side); d=np.array(d)
for k in [1,2,3,4]:
  for o in ['last=max','last=min','mid']:
    for sd in ['below','above']:
      for lo,hi in [(1,3),(4,10),(11,30)]:
        m=(n==k)&(order==o)&(side==sd)&(d>=lo)&(d<=hi)&(cat!='ex')
        if m.sum()>15: print(k,o,sd,lo,hi,m.sum(),'obs %.3f inc %.3f'%(y[m].mean(),pi[m].mean()))
EOF
/scr/wurgaft/auto-psych/agent_trees/45bd45c333332e1a/venv/bin/python scratch/ord.py

